create or replace function public.cancel_booking(p_booking_id uuid) returns public.bookings language plpgsql security definer set search_path=public as $$declare b public.bookings;begin if auth.uid() is null then raise exception 'Authentication required';end if;update public.bookings set status='cancelled',updated_at=now() where id=p_booking_id and user_id=auth.uid() and status in('pending_payment','confirmed') returning * into b;if b.id is null then raise exception 'BOOKING_NOT_FOUND_OR_NOT_CANCELLABLE';end if;update public.payments set status='cancelled',updated_at=now() where booking_id=b.id and status='pending';return b;end;$$;revoke all on function public.cancel_booking(uuid) from public;grant execute on function public.cancel_booking(uuid) to authenticated;